#include <spanstream>
#include <utility>
#include <cassert>
#include <iostream>

int main() {
    char buffer[16] = "42";
    std::ospanstream stream{std::span<char>{buffer}};
    stream << 73;
    assert(buffer[0] == '7' && buffer[1] == '3');
    assert(stream.rdbuf() != nullptr);
    char backup[16]{};
    std::ospanstream other{std::span<char>{backup}};
    other = std::move(stream);
    other.swap(stream);
    std::swap(other, stream);
    std::cout << "Checks passed\n";
}
